  | { type: "SAMPLE_CHANGED"; id: string }
  | { type: "RESET" }
  | { type: "TAB_CHANGED"; tab: "threads" | "graph" }
  | { type: "GRAPH_MSG"; msg: GraphMsg }
  | { type: "TOGGLE_EXPANDED"; index: number }
  | { type: "CHANGE_CLICKED"; id: GraphId }
  | { type: "CHILD_MSG"; msg: ThreadPaneMsg };

