            if (msg.type === "TOGGLE_EXPANDED")
              dispatch({ type: "TOGGLE_EXPANDED", index: i });
          },
        ),
      ),
    );
  }

  sync(state: UpdatePaneState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

END

